let active=false,tab='notes',query='',editing=null,journalMonth='',journalSubject='',onlyFavorites=false,noteCategory='all',noteSubject='',journalEditing=null,pendingFiles=[],fileLoading=false,journalView='overview',journalWeekOffset=0,journalDay='',noteView='subjects',noteEditorOpen=false,notebookHelp=localStorage.getItem('dpn_help_dismissed')!=='1',friendVisibility=true,notebookToolsOpen=false,socialThreadList=true,lessonDetail=null,scheduleLessons=[],scheduleStatus='Завантаження розкладу…';
const labels={notes:'Конспекти',chats:'Чати',friends:'Друзі',journal:'Журнал'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[c]));
const get=k=>{try{const a=JSON.parse(localStorage.getItem('dp_notebook_'+k));return Array.isArray(a)?a:[]}catch{return []}};
const set=(k,v)=>{try{localStorage.setItem('dp_notebook_'+k,JSON.stringify(v));return true}catch(e){alert('Не вдалося зберегти запис: недостатньо місця.');return false}};
const date=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
